function pickWeighted(pool) {
    const total = pool.reduce((sum, u) => sum + u.weight, 0);
    let r = Math.random() * total;
    for (const u of pool) {
        r -= u.weight;
        if (r < 0) return u;
    }
    return pool[pool.length - 1];
}

